import random
import sys
from datetime import datetime, timedelta

sys.path.insert(0, "/private/tmp/tmpxmhbm3y7/pete/projects/devkit")
from devkit import cron, ini, table

random.seed(12345)

# ---------------- table fuzz ----------------
ALIGNS = [None, "left", "right", "center"]


def rand_text():
    alphabet = "abcXYZ 019_-."
    return "".join(random.choice(alphabet) for _ in range(random.randrange(0, 9)))


def rand_cell():
    r = random.random()
    if r < 0.15:
        return None
    if r < 0.3:
        return random.randrange(-100, 100)
    text = rand_text()
    if random.random() < 0.3:
        text += "|" + rand_text()
    return text


for trial in range(3000):
    ncols = random.randrange(1, 6)
    header = [rand_cell() for _ in range(ncols)]
    nrows = random.randrange(0, 6)
    rows = []
    for _ in range(nrows):
        width = random.randrange(0, ncols + 1)
        rows.append([rand_cell() for _ in range(width)])
    align = [random.choice(ALIGNS) for _ in range(ncols)]
    text = table.format_table(header, rows, align)
    h, r, a = table.parse_table(text)
    want_h = [("" if v is None else str(v)) for v in header]
    want_r = []
    for row in rows:
        cells = [("" if v is None else str(v)) for v in row]
        cells += [""] * (ncols - len(cells))
        want_r.append(cells)
    assert h == want_h, (trial, h, want_h, text)
    assert r == want_r, (trial, r, want_r, text)
    assert a == align, (trial, a, align, text)
    assert table.format_table(h, r, a) == text, (trial, text)

# ---------------- cron fuzz ----------------
MONTHS = {"JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
          "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12}
DOWS = {"SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6}


def val(text, names):
    if names and text.upper() in names:
        return names[text.upper()]
    return int(text)


def expand(text, lo, hi, names=None):
    out = set()
    for item in text.split(","):
        step = 1
        base = item
        if "/" in item:
            base, s = item.split("/")
            step = int(s)
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            x, y = base.split("-")
            a, b = val(x, names), val(y, names)
        else:
            a = val(base, names)
            b = hi if "/" in item else a
        out.update(range(a, b + 1, step))
    return out


def brute(expr, after, limit):
    f = expr.split()
    mins = expand(f[0], 0, 59)
    hrs = expand(f[1], 0, 23)
    doms = expand(f[2], 1, 31)
    mons = expand(f[3], 1, 12, MONTHS)
    dows = {x % 7 for x in expand(f[4], 0, 7, DOWS)}
    t = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    while t <= limit:
        dow = (t.weekday() + 1) % 7
        if f[2] != "*" and f[4] != "*":
            dayok = t.day in doms or dow in dows
        else:
            dayok = t.day in doms and dow in dows
        if t.month in mons and t.hour in hrs and t.minute in mins and dayok:
            return t
        t += timedelta(minutes=1)
    return None


# Random expressions biased to match often enough for brute force.
def rand_item(lo, hi, names=None, allow_step=True):
    r = random.random()
    if r < 0.35:
        base = "*"
    elif r < 0.55:
        base = str(random.randint(lo, hi))
    else:
        a = random.randint(lo, hi)
        b = random.randint(a, hi)
        if names and random.random() < 0.4:
            inv = {v: k for k, v in names.items()}
            base = inv[a] + "-" + inv[b]
        else:
            base = "%d-%d" % (a, b)
    if allow_step and random.random() < 0.25:
        base += "/" + str(random.randint(1, max(1, hi - lo + 1)))
    return base


for trial in range(400):
    minute = rand_item(0, 59)
    hour = rand_item(0, 23)
    dom = rand_item(1, 28)
    month = rand_item(1, 12, MONTHS)
    dow = rand_item(0, 6, DOWS)
    expr = " ".join([minute, hour, dom, month, dow])
    after = datetime(2023, 1, 1) + timedelta(
        days=random.randrange(0, 900),
        hours=random.randrange(0, 24),
        minutes=random.randrange(0, 60),
        seconds=random.randrange(0, 60),
    )
    limit = after + timedelta(days=120)
    expected = brute(expr, after, limit)
    try:
        got = cron.next_run(expr, after)
    except ValueError:
        got = None
    assert got == expected, (trial, expr, after, got, expected)

# ---------------- ini ordering fuzz ----------------
for trial in range(500):
    text = ""
    want = {}
    order = []
    sections = ["s" + str(i) for i in range(5)]
    for _ in range(random.randrange(1, 30)):
        r = random.random()
        if r < 0.15:
            sec = random.choice(sections)
            text += "[%s]\n" % sec
            if sec not in want:
                want[sec] = {}
                order.append(sec)
        elif r < 0.8:
            sec = random.choice(order) if order else None
            if sec is None:
                continue
            key = random.choice(["a", "b", "c", "d"])
            value = random.choice(["1", "2", "hello", "x=y", "p:q", ""])
            text += "%s = %s\n" % (key, value)
            want[sec][key] = value
        else:
            text += "\n" if random.random() < 0.5 else "# comment\n"
    if not order:
        continue
    got = ini.parse(text)
    assert list(got) == order, (trial, text, list(got), order)
    for sec, keys in want.items():
        assert list(got[sec]) == list(keys), (trial, text, sec, got[sec], keys)
        assert got[sec] == keys, (trial, text, sec, got[sec], keys)

print("FUZZ PASSED")

